using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace Tralys.Ui.CodeGen;

static class Output
{
    static readonly DiagnosticDescriptor DuplicateHintName = Descriptors.Error(
        "TRL0001",
        "Duplicate generated file name",
        "Two inputs both generate '{0}'; only the first was emitted"
    );

    public static void Header(CodeWriter w)
    {
        w.Line("// <auto-generated/>");
        w.Line("#nullable enable");
        w.Line();
    }

    public static void Namespace(CodeWriter w, string? ns)
    {
        if (ns is not { Length: > 0 })
            return;

        w.Line($"namespace {ns};");
        w.Line();
    }

    public static IncrementalValueProvider<string> RootNamespace(
        IncrementalGeneratorInitializationContext context
    ) =>
        context.AnalyzerConfigOptionsProvider.Select(
            static (options, _) =>
                options.GlobalOptions.TryGetValue("build_property.RootNamespace", out var value)
                    ? value
                    : ""
        );

    public static Location AtFile(string path) =>
        Location.Create(path, default, new LinePositionSpan(default, default));

    // Roslyn compares hint names ignoring case where C# names do not, so the case is hashed in.
    public static string HintName(string name, string suffix)
    {
        var hash = 2166136261u;
        foreach (var c in name)
            hash = unchecked((hash ^ c) * 16777619u);

        return $"{name}.{hash:x8}.{suffix}";
    }

    public static void Add(SourceProductionContext context, string hintName, string source)
    {
        try
        {
            context.AddSource(hintName, source);
        }
        catch (ArgumentException)
        {
            context.ReportDiagnostic(Diagnostic.Create(DuplicateHintName, Location.None, hintName));
        }
    }
}
